import torch
import torch.nn as nn

class PartiallyTrainableLinear(nn.Module):
    def __init__(self, in_features, out_features, trainable_ratio=0.041):
        super().__init__()
        n_train = int(out_features * trainable_ratio)
        self.trainable = nn.Linear(in_features, n_train)
        self.fixed = nn.Linear(in_features, out_features - n_train)
        self.fixed.weight.requires_grad = False
        self.fixed.bias.requires_grad = False

    def forward(self, x):
        return torch.cat([self.trainable(x), self.fixed(x)], dim=-1)
